#!/usr/bin/env python3
import sys
from common import call_api, check_api_response

def cancel_order(order_id):
    return call_api("cancelOrder", order_id)

def display_cancel_result(response):
    if not check_api_response(response, "取消订单失败"):
        return

    print("\n" + "=" * 80)
    print("✅ 订单取消成功！")
    print("=" * 80)

def main():
    if len(sys.argv) != 2:
        print("用法: python3 cancel_order.py <order_id>")
        print("示例: python3 cancel_order.py 69a677bee4b0252bd532e35c")
        sys.exit(1)

    order_id = sys.argv[1]

    print(f"\n正在取消订单...")
    print(f"订单号: {order_id}")

    response = cancel_order(order_id)
    display_cancel_result(response)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import sys
import json
from common import call_api, check_api_response, format_timestamp

def get_order_detail(order_id):
    return call_api("orderDetail", order_id)

def display_order_detail(response):
    if not check_api_response(response, "查询订单详情失败"):
        return

    data = response.get("data", {})

    order_id = data.get("orderId", "")
    status_obj = data.get("status", {})
    order_status_key = status_obj.get("key", "") if status_obj else ""
    order_status_text = status_obj.get("value", "") if status_obj else ""
    create_time = data.get("createTime", "")
    pay_deadline = data.get("payDeadline", "")

    segment_info = data.get("segmentInfo", {})
    flight_no = segment_info.get("flight_no", "")
    departure_timestamp = segment_info.get("departure_timestamp", 0)
    arrived_timestamp = segment_info.get("arrived_timestamp", 0)
    starting_airport = segment_info.get("starting_airport", "")
    destination_airport = segment_info.get("destination_airport", "")
    starting_terminal = segment_info.get("starting_terminal", "")
    destination_terminal = segment_info.get("destination_terminal", "")
    seat_msg = segment_info.get("seat_msg", "")
    airline_name = segment_info.get("airline_name", "")
    plane_type = segment_info.get("plane_type", "")

    passenger_list = data.get("passengerList", [])

    price_detail = data.get("priceDetail", [])
    change_refund_price_detail = data.get("changeRefundPriceDetail", [])

    if change_refund_price_detail:
        final_price_detail = change_refund_price_detail
    else:
        final_price_detail = price_detail

    order_total_price = data.get("orderTotalPrice", 0)

    def format_price(price):
        return f"¥{int(price)}" if price == int(price) else f"¥{price}"

    print("\n" + "=" * 80)
    print("订单详情")
    print("=" * 80)

    print(f"\n订单号: {order_id}")
    if order_status_text or order_status_key:
        print(f"订单状态: {order_status_text}")
    if create_time:
        print(f"创建时间: {create_time}")
    if pay_deadline:
        print(f"支付截止时间: {pay_deadline}")

    print(f"\n航班信息:")
    if airline_name:
        print(f"- 航空公司: {airline_name}")
    if flight_no:
        print(f"- 航班号: {flight_no}")
    if departure_timestamp:
        print(f"- 出发时间: {format_timestamp(departure_timestamp, '%Y-%m-%d %H:%M')}")
    if arrived_timestamp:
        print(f"- 到达时间: {format_timestamp(arrived_timestamp, '%Y-%m-%d %H:%M')}")
    if starting_airport:
        airport_info = starting_airport
        if starting_terminal:
            airport_info += f" {starting_terminal}航站楼"
        print(f"- 出发机场: {airport_info}")
    if destination_airport:
        airport_info = destination_airport
        if destination_terminal:
            airport_info += f" {destination_terminal}航站楼"
        print(f"- 到达机场: {airport_info}")
    if seat_msg:
        print(f"- 舱位: {seat_msg}")
    if plane_type:
        print(f"- 机型: {plane_type}")

    if passenger_list:
        print(f"\n乘客信息:")
        for idx, passenger in enumerate(passenger_list, 1):
            passenger_info = passenger.get("passengerInfo", {})
            name = passenger_info.get("name", "")
            phone = passenger_info.get("phone", "")
            id_card = passenger_info.get("identity_no", "")
            id_type_name = passenger_info.get("identity_type_name", {}).get("value", "")
            ticket_no = passenger.get("ticketNo", "")

            if name:
                print(f"  - 姓名: {name}")
            if phone:
                print(f"  - 联系电话: {phone}")
            if id_card and id_type_name:
                print(f"  - 证件类型: {id_type_name}")
                print(f"  - 证件号: {id_card}")
            if ticket_no:
                print(f"  - 票号: {ticket_no}")

    if final_price_detail:
        print(f"\n价格信息:")
        for item in final_price_detail:
            key = item.get("key", "")
            price = item.get("price", 0)
            amount_desc = item.get("amountDesc", "")
            if key and price is not None:
                desc = f" ({amount_desc})" if amount_desc else ""
                print(f"- {key}: {format_price(price)}{desc}")
        if order_total_price > 0:
            print(f"- 总金额: {format_price(order_total_price)}")

    print("\n" + "=" * 80)

def main():
    if len(sys.argv) != 2:
        print("用法: python3 order_detail.py <order_id>")
        print("示例: python3 order_detail.py 69a677bee4b0252bd532e35c")
        sys.exit(1)

    order_id = sys.argv[1]

    print(f"\n正在查询订单详情...")
    print(f"订单号: {order_id}")

    response = get_order_detail(order_id)
    display_order_detail(response)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
查询航班退改规则
从 flight_seat_items.json 读取舱位信息，调用 searchGuestRule API 查询退改规则
"""
import json
import sys
from common import call_api, check_api_response, get_temp_file_path


def display_guest_rule(response, seat_item):
    """格式化展示退改规则"""
    if not check_api_response(response, "查询退改规则失败"):
        return

    data = response.get("data", {})
    stipulate = data.get("stipulate", {})

    if not stipulate:
        print("未找到退改规则信息")
        return

    # 获取舱位基本信息
    cabin = stipulate.get("cabin", "")
    par_price = stipulate.get("par_price", 0)
    product_name = seat_item.get("product_name", "")
    discount = seat_item.get("discount", 0)

    print("\n" + "=" * 100)
    print(f"舱位信息: {product_name} | {cabin}舱 | 票面价 ¥{int(par_price)}")
    print("=" * 100)

    # 退票规则
    refund_stipulate = stipulate.get("refund_stipulate", "")
    if refund_stipulate:
        print("\n【退票规则】")
        print("-" * 100)
        try:
            rules = refund_stipulate.split(",")
            for rule in rules:
                rule = rule.strip()
                if rule and not rule.startswith("*"):
                    print(f"  • {rule}")
                elif rule.startswith("*"):
                    print(f"\n{rule}")
        except Exception:
            print(f"  {refund_stipulate}")

    # 改期规则
    change_stipulate = stipulate.get("change_stipulate", "")
    if change_stipulate:
        print("\n【改期规则】")
        print("-" * 100)
        try:
            rules = change_stipulate.split("。")
            for rule in rules:
                rule = rule.strip()
                if rule and not rule.startswith("*"):
                    print(f"  • {rule}")
                elif rule.startswith("*"):
                    print(f"\n{rule}")
        except Exception:
            print(f"  {change_stipulate}")

    # 签转规则
    modify_stipulate = stipulate.get("modify_stipulate", "")
    if modify_stipulate:
        print("\n【签转规则】")
        print("-" * 100)
        print(f"  {modify_stipulate}")

    # 行李额
    baggage_info = stipulate.get("baggage_info", {})
    if baggage_info:
        print("\n【行李额】")
        print("-" * 100)
        try:
            # 托运行李
            check_in = baggage_info.get("checkInBaggage", {})
            if check_in.get("flag"):
                context = check_in.get("context", "")
                if context:
                    for line in context.split("\n"):
                        if line.strip():
                            print(f"  • {line.strip()}")

            # 手提行李
            carry_on = baggage_info.get("carryOnBaggage", {})
            if carry_on.get("flag"):
                context = carry_on.get("context", "")
                if context:
                    for line in context.split("\n"):
                        if line.strip():
                            print(f"  • {line.strip()}")

        except Exception:
            # 兜底：展示原始行李额信息
            baggage_context = baggage_info.get("baggage_context", "")
            if baggage_context:
                print(f"  {baggage_context}")
            else:
                print(f"  {str(baggage_info)}")

    print("\n" + "=" * 100)

def load_seat_items():
    """从文件加载舱位信息"""
    seat_items_file = get_temp_file_path("flight_seat_items.json")

    try:
        with open(seat_items_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
            return data
    except FileNotFoundError:
        print("错误: 未找到舱位信息文件")
        print("请先执行舱位详情查询（searchPrice）")
        return None
    except json.JSONDecodeError:
        print("错误: 舱位信息文件格式错误")
        return None


def main():
    if len(sys.argv) != 2:
        print("用法: python3 search_guest_rule.py <seat_index>")
        print("示例: python3 search_guest_rule.py 1")
        sys.exit(1)

    try:
        seat_index = int(sys.argv[1])
    except ValueError:
        print("错误: 舱位编号必须是数字")
        sys.exit(1)

    # 加载舱位信息
    data = load_seat_items()
    if not data:
        sys.exit(1)

    seat_items = data.get("seat_items", [])
    flight_info = data.get("flight_info", {})

    # 验证舱位编号
    if seat_index < 1 or seat_index > len(seat_items):
        print(f"错误: 舱位编号无效，请选择 1-{len(seat_items)} 之间的编号")
        sys.exit(1)

    # 获取选中的舱位
    selected_seat = seat_items[seat_index - 1]

    print(f"\n正在查询退改规则...")
    print(f"航班号: {flight_info.get('flight_no', '')}")
    print(f"舱位: {selected_seat.get('product_name', '')}")

    # 移除 display_index，避免传递到后端
    seat_item_copy = selected_seat.copy()
    if "display_index" in seat_item_copy:
        del seat_item_copy["display_index"]

    # 构建业务参数 - 使用舱位信息中的所有相关字段
    business_params = {
       **seat_item_copy,
    }

    # 调用 API
    response = call_api("searchGuestRule", business_params)

    # 格式化展示退改规则
    display_guest_rule(response, selected_seat)


if __name__ == "__main__":
    main()

